# Re-analyze: Based on demo patterns, let me try filling ALL gaps within component bounding boxes
import copy

def compute_bounding_box(grid):
    """Compute bounding box for all non-zero cells"""
    min_r, max_r = len(grid), 0
    min_c, max_c = len(grid[0]), 0
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] != 0:
                min_r = min(min_r, r)
                max_r = max(max_r, r)
                min_c = min(min_c, c)
                max_c = max(max_c, c)
    return min_r, max_r, min_c, max_c

