def get_band_bbox(grid, start_row, end_row):
    """Get bounding box of 7s in specified row range"""
    min_r, max_r = end_row, start_row
    min_c, max_c = 28, -1

    for r in range(start_row, end_row + 1):
        for c in range(28):
            if grid[r][c] == 7:
                min_r = min(min_r, r)
                max_r = max(max_r, r)
                if max_c == -1 or c < min_c:
