import json
from collections import deque

test_grid_copy = [row[:] for row in test_grid]

# Strategy T: Flood fill from edges to mark reachable cells, then fill unreachable (enclosed) zeros with 1
solution_t = [row[:] for row in test_grid]

def flood_fill_unreachable(grid):
    """Mark all zeros reachable from grid edges"""
    m, n = len(grid), len(grid[0])
    reachable = [[False]*n for _ in range(m)]

    # Queue for BFS from all edge cells that are 0
    queue = deque()
    for c in range(n):
        if grid[0][c] == 0:
            queue.append((0, c))
            reachable[0][c] = True
        if grid[m-1][c] == 0:
            queue.append((m-1, c))
            reachable[m-1][c] = True

    for r in range(1, m-1):
        if grid[r][0] == 0:
            queue.append((r, 0))
            reachable[r][0] = True
        if grid[r][n-1] == 0:
            queue.append((r, n-1))
            reachable[r][n-1] = True

    while queue:
        r, c = queue.popleft()
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < m and 0 <= nc < n:
                if not reachable[nr][nc] and grid[nr][nc] == 0:
                    reachable[nr][nc] = True
                    queue.append((nr, nc))

    return reachable

